module Card::Searchable
  extend ActiveSupport::Concern

  included do
    scope :search, ->(query) {
      if query.blank?
        none
      else
        where(id: Card::Searchable.matching_ids(query))
      end
    }
  end

  class << self
    def matching_ids(query)
      pattern = "%#{Card.sanitize_sql_like(query)}%"

      Card.left_joins(:rich_text_description, comments: :rich_text_body)
        .where("cards.title LIKE :q OR action_text_rich_texts.body LIKE :q OR rich_text_bodies_comments.body LIKE :q", q: pattern)
        .select(:id)
    end
  end
end
